export const meta = { name: "relate-pipeline", description: "The entire data pipeline for the Relate Graph Space (the Space is only a client on top of the Relate database; this workflow is the engine). Covers the pipeline from EVERY point: import, ontology, categorizing, normalization, cleaning, embeddings, communities, processing — plus dream, a consolidation pass (summarize missing SourceDocument summaries, embed unembedded content nodes, refresh communities, and a report-only lead-grade similarity candidate scan that writes no SIMILAR_TO edges and merges nothing), plus query, an answering job that runs the agentic GraphRAG loop (skill §8) with read-only tools and writes nothing. Imports of prose sources run a dedicated extraction stage first (Cognee contract: deterministic chunking via the CLI, per-chunk KnowledgeGraph extraction, every relationship edge carrying its one-sentence fact, applied via the typed `extract` tool) so imports produce fact edges, not just document-attachment edges. One job in (category: import | ontology | categorizing | normalization | embeddings | communities | processing | cleaning | query | full-pipeline | dream), every stage runs in order, each stage doing the work when the job calls for it or returning a quick audited skip when it does not. The ontology stage is governed by the packaged house ontology (custom.relate ontology pack: house-memory-graph.ttl, with the standards as reference/mapping targets only); mechanical stages run as thin wrappers over the deterministic custom.relate CLI tools (counts/labels/types, stamp, reconcile, scan-conflicts, embed-missing, verify — JSON in/out, no improvised Cypher; reasoning is used only where it is needed); an independent verifier runs the verify tool (the pack's Part A gates, in-graph ontology conformance, contradiction gate) and cross-checks every stage claim against its output; one bounded repair loop (deterministic fixers only), then the outcome writes back into the Space's agent request (requested -> running -> done/failed) when a requestId is passed. The graph builds ONLY from sources named in the job; identities are never merged on similarity alone; contradictions are handled by retire-and-link supersession (SUPERSEDED_BY) or contested marking with human review — never by silent overwrite. The ontology branch also carries an auto-ontology INDUCTION stage (NVIDIA steal: deterministic corpus profile first, then ONE reasoning step proposing a draft ontology under a restrictive evidence contract, written as a Turtle draft pack under ~/workspace/relate-space/ontology-drafts/ plus a review item — a draft is NEVER stamped by the pipeline; stamping stays a separate approved ontology job). The normalization stage runs the RESOLUTION FUNNEL (Graphiti/Utopia steal, report-only machinery): blocking via normalize-scan, pairwise scoring via similar-scan cosines attached to each blocked pair, and cluster QA with bridge-pair flags — the funnel itself merges nothing.", phases: ["intake", "ontology", "induction", "extraction", "import", "categorizing", "normalization", "cleaning", "summarize", "embeddings", "communities", "candidates", "query", "verify", "writeback"] };

const inputs = args ?? {};
const category = inputs.category || "full-pipeline";
const task = inputs.task || "";
const source = inputs.source || "";
const nodeContext = inputs.nodeContext || "";
const requestId = inputs.requestId || "";
const spaceSlug = inputs.spaceSlug || "relate-graph";
const requestedAt = inputs.requestedAt || "";
const apiBase = inputs.apiBase || "http://127.0.0.1:7475";
const graphName = inputs.graphName || "main";
const induce = inputs.induce || "";

const ctxParts = [
  "SHARED CONTEXT — Relate Graph pipeline job.",
  "Job category: " + category + ". Job task: " + (task || "(none given)") + ". Source named in job: " + (source || "(none)") + ". Node context: " + (nodeContext || "(none)") + ". Requested at: " + (requestedAt || "(not given)") + ". TARGET GRAPH: '" + graphName + "' at " + apiBase + " — every query in this job goes to THIS graph's API and no other.",
  "DATABASE: Relate by Neo4j, reached ONLY through the typed CLI at ~/workspace/custom-connectors/custom.relate/bin/relate (slug = this job's graphName) — the CLI binds every value as a parameter, enforces the ontology/provenance/contradiction gates, and wraps multi-statement writes in managed transactions. Never hand-build HTTP calls or interpolate values into Cypher strings: if a read is not covered by a named CLI command, use the CLI's `query` command and keep the statement static. Graph registry (name -> store file, port, service): ~/workspace/relate-space/graphs/registry.json — the main graph is space-graph.rl on port 7475 (service relate-api.service); other graphs are graphs/<slug>.rl on their own ports (service relate-graph@<slug>.service).",
  "EMBEDDINGS RUNTIME: local Ollama with model embeddinggemma-2 (768-dim output) under ~/workspace/relate-runtime/ (models in ~/workspace/relate-runtime/models). The format contract is owned by the CLI tools, never by stage text: node vectors use the EmbeddingGemma 2 document format (marker eg2-doc-v1), edge fact sentences the symmetric sentence-similarity format (eg2-sym-v1), and nodes record the RESOLVED model identity, never the mutable tag. If Ollama is not answering on 127.0.0.1:11434, the CLI tools relaunch it themselves; you never call Ollama directly.",
  "HARD RULES: (1) The graph builds ONLY from sources named in this job — never import the old urbex/OSINT graph or anything under research_notes. (2) Never merge two nodes into one identity on similarity alone — merges need evidence (shared handle, explicit alias statement, or the job's own instruction). (3) SIMILAR_TO edges are LEAD-grade only (property confidence:'lead') and are created only when the job explicitly asks for a similarity pass. (4) After ANY write, re-query node and edge counts and report before/after in your summary. (5) If a stage does not apply to this job's category, return status 'skipped' with the reason — do not invent work. (6) Report blockers honestly; a blocked stage is a valid result, a fabricated success is not.",
  "SPACE WRITEBACK: the Space (slug '" + spaceSlug + "') is the client. When a requestId is provided, its published actions include updateAgentRequest {id, status, result} and listAgentRequests {} — invoke them with the artifact tools (artifact.invoke_action). This job's requestId: " + (requestId || "(none — no writeback)") + "."
];

ctxParts.push("ONTOLOGY PACK: ~/workspace/custom-connectors/custom.relate/ontologies/ (index: ~/workspace/custom-connectors/custom.relate/ONTOLOGIES.md — read it when a job touches schema or verification). The house ontology house-memory-graph.ttl is the GOVERNING schema for the memory/people graph family (labels Person/Group/SourceDocument/Question/SpaceSignal, plus the Ontology/OntologyClass/OntologyProperty stamp labels; types MENTIONS/DESCRIBED_IN/IN_JOHNNYS_NETWORK/ABOUT/ASSISTANT_OF/MEMBER_OF/SUPERSEDED_BY; datatype keys slug/name/legalName/alias/normalizedName/normalizedSlug/category/community/sourcePath/summary/validFrom/validTo/recordedAt/retiredAt/embedding/embedding_dim/embedding_model). Its Cypher twin house-memory-graph.cypher holds Part A (read-only validation queries — the verify stage runs them as gates) and Part B (an ontology stamp — write Cypher, run ONLY when a job explicitly asks for ontology stamping). Standard mappings per ONTOLOGIES.md: FOAF + schema.org = people and organizations, PROV-O = provenance, OWL-Time = temporal patterns, SKOS = categories, Dublin Core Terms = documents, W3C ORG = formal org structure. PRESET RESOLUTION: when a job's task text names an ontology preset, resolve the name to its pack file — schema.org -> schema-org.jsonld, FOAF -> foaf.rdf, PROV-O -> prov-o.ttl, OWL-Time -> owl-time.ttl, SKOS -> skos.rdf, Dublin Core -> dcterms.rdf, W3C ORG -> org.ttl, House -> house-memory-graph.ttl. APPLYING AN ONTOLOGY MATERIALIZES IT INTO THE GRAPH (Johnny's rule: apply the OWL to the graph, not independently): an apply job stamps the vocabulary into the target graph as one (:Ontology) node (name, sourceFile, version, appliedAt) plus its (:OntologyClass) and (:OntologyProperty) nodes — each carrying its standard-term mapping as properties — linked by DEFINES_CLASS / DEFINES_PROPERTY edges, MERGE-based so re-applying is idempotent and updates in place. The pack files stay the source documents the stamp is generated from; the stamped in-graph ontology then GOVERNS the graph: imports and categorizing conform to its defined classes/properties, and the verifier checks the graph's data against it. Never import a standard wholesale as graph DATA (its terms become ontology-stamp nodes, not content nodes), and never leave an applied ontology as an external side reference only.");

ctxParts.push("CONTRADICTION HANDLING (all write stages): before writing, check for contradictions — (a) a single-valued property (one the in-graph ontology marks single-valued; at minimum SourceDocument.sourcePath and Person.legalName) where the graph already holds a different live value; (b) a new edge conflicting with an existing edge between the same pair (an incompatible type, or the same type with a contradictory qualifier); (c) identity-level conflicts (two nodes claiming the same unique identifier with incompatible facts). Record EVERY detected contradiction in your stage result with both sides and their sources — never silently drop one. Resolution has exactly two paths: (1) VERIFIABLY SUPERSEDED (the new fact carries stronger or newer source evidence — a later-dated source, or the source document itself correcting an earlier extraction): retire-and-link — set retiredAt on the old fact (and close validTo when a valid interval exists), write the corrected fact with recordedAt set, and link old -> new with a SUPERSEDED_BY edge; the old fact is NEVER overwritten or deleted, so the as-recorded view still shows what was believed before. (2) UNDECIDABLE (two sources assert incompatible facts and neither is verifiably wrong): keep BOTH facts, mark the pair contested (contested: true plus a contestedWith note naming the other side, on both facts), and enqueue a review item in your stage result naming the explicit human choices (keep A / keep B / keep both as disputed). Nothing auto-resolves an undecidable contradiction.");

ctxParts.push("INDUCTION FLAG: job arg induce = '" + (induce || "(not set)") + "'. The induction stage runs only when this flag is set (any non-empty value) OR the job's task text asks for induction (induce / induction / draft ontology / vocabulary discovery over the corpus). The flag's presence is a fact from the job args, not something to infer. A draft ontology produced by induction is NEVER stamped by this pipeline — stamping stays a separate approved ontology job.");

ctxParts.push("DETERMINISM (Johnny's mandate — typed tools, no vibes): mechanical operations run through the custom.relate CLI at ~/workspace/custom-connectors/custom.relate/bin/relate (JSON in/out, fixed behavior; <graph> is the registry slug = this job's graphName): counts/labels/types (census), stamp <graph> <preset> (materialize an ontology into the graph, full vocabulary, keyed by name), reconcile <graph> (merge duplicate ontology bookkeeping into the keyed nodes), scan-conflicts <graph> (contradiction detection scan), embed-missing <graph> (embed every unembedded node the tool's contract covers), verify <graph> (ALL verification gates: Part A, duplicate ontology names, in-graph conformance, contradiction gate). Phase-2 tools in the same CLI: write-batch <graph> <batch.json> (the ONLY sanctioned write path for extracted data and mechanical fixes — validates the WHOLE batch against the in-graph ontology and live graph first, requires provenance on every item and a one-sentence 'fact' on every fact edge, then applies atomically in one managed transaction, MERGE on slug; a refusal anywhere refuses the batch), chunks <file> + extract <graph> <extraction.json> (the triplet-extraction pair: deterministic chunking + the Cognee contract, then validated conversion with identity-by-construction slugs), normalize-scan <graph> (read-only normalization candidate pairs by fixed rules), categorize <graph> (deterministic ontology category rules, residue listed for reasoning), clean-scan <graph> (read-only findings: duplicates, self-references, isolated nodes, undeclared labels/types), communities <graph> (deterministic label propagation writing the community property), embed-edges <graph> (embed edge fact sentences for triplet retrieval). CORRECTIONS ARE TOOLS, NEVER HAND-EXECUTED SEQUENCES: a decided correction runs through supersede <graph> <fact-ref-json> <batch.json> (retire-and-link as ONE typed command — it retires the old fact, preserves it in supersededValues, writes the correction with recordedAt, links SUPERSEDED_BY, writes the Decision, and re-scans; it refuses anything undecidable); identity merges run through merge <graph> <winner> <loser> <basis-json> (reversible via unmerge <graph> <decision-id>); ontology renames run through rename <graph> <class|property> <old> <new>. Never hand-execute retire-and-link or merge Cypher. A stage whose tool is missing or exits with an error fails honestly with that error — never improvise around a missing tool. When your stage is a mechanical step, run the exact tool command and build your stage result from its JSON — do NOT improvise Cypher for that operation, do NOT interpret or 'fix' tool output; if the tool exits with an error, return status 'failed' with the tool's error text in blockers. Reasoning (your judgment) is reserved for: extraction from source text (filling the extraction contract), summarization, genuinely ambiguous categorizing, merge-evidence calls, the superseded-vs-undecidable call, and preparing review items. Every write a reasoning stage makes is bracketed by the deterministic tools (scan-conflicts before, the run's verify stage after). The CLI's query command is the typed escape hatch for reads the named commands do not cover.");

if (category === "dream") {
  ctxParts.push("DREAM JOB RULES (category 'dream' — a consolidation pass over the target graph): never delete anything; never merge identities; never import new sources; write ONLY to the target graph named above, and only properties (summary, embedding/embedding_dim/embedding_model, community, communitySummary) — no new nodes, no new edges; node and edge counts at the end of the run must be identical to what intake measured; SIMILAR_TO edges are NEVER written in a dream run — similarity findings are lead-grade report text only.");
}

const CTX = ctxParts.join("\n");

const stageSchema = {
  type: "object",
  properties: {
    status: { type: "string", enum: ["done", "skipped", "blocked", "failed"] },
    summary: { type: "string" },
    changes: { type: "array", items: { type: "string" } },
    blockers: { type: "array", items: { type: "string" } },
    nodesAfter: { type: ["number", "null"] },
    edgesAfter: { type: ["number", "null"] }
  },
  required: ["status", "summary", "changes", "blockers"]
};

const verifySchema = {
  type: "object",
  properties: {
    passed: { type: "boolean" },
    nodes: { type: ["number", "null"] },
    edges: { type: ["number", "null"] },
    evidence: { type: "array", items: { type: "string" } },
    discrepancies: { type: "array", items: { type: "string" } }
  },
  required: ["passed", "evidence", "discrepancies"]
};

function stagePrompt(stage, instruction, prior) {
  return CTX + "\n\nYOU ARE THE '" + stage + "' STAGE of the relate-pipeline workflow (job category: " + category + ").\n" + instruction + "\n\nResults of earlier stages in this run (JSON): " + JSON.stringify(prior) + "\n\nReturn ONLY the JSON stage-result object with exactly these fields: status (done/skipped/blocked/failed), summary (plain text, with real before/after counts when you wrote anything), changes (array of concrete change strings), blockers (array), and nodesAfter/edgesAfter when you know them. No prose outside the JSON object. Evidence or it did not happen.";
}

phase("intake");
const intake = await agent(stagePrompt("intake",
  "DETERMINISTIC STEP — no improvised queries. Run exactly these commands for the target graph (slug = this job's graphName): ~/workspace/custom-connectors/custom.relate/bin/relate counts <graph>, ~/workspace/custom-connectors/custom.relate/bin/relate labels <graph>, ~/workspace/custom-connectors/custom.relate/bin/relate types <graph>. Build your stage result from their JSON output verbatim: total nodes, total edges, label counts, type counts. Restate the job scope in one or two sentences: what this run will and will not do. If a requestId is provided, FIRST mark the Space request as running via updateAgentRequest {id: requestId, status: 'running'}. Do not write any graph data in this stage." + (category === "dream" ? " DREAM INTAKE: also run ~/workspace/custom-connectors/custom.relate/bin/relate verify <graph> and take the COVERAGE before-numbers from its JSON gate details: embedding coverage (A9 — content nodes with/without 'embedding', the (embedding_dim, embedding_model) pairs in use), summary coverage (A13 — SourceDocuments with/without 'summary'), community coverage (A15 — content nodes with/without 'community'). These before-numbers are what the dream stages must improve and what the verifier compares against. If a coverage number is absent from the tool output, record 'not reported by verify tool' for it in blockers — never improvise a query to fill it." : ""),
  {}), { key: "intake", label: "Intake — read graph state", schema: stageSchema, timeoutMs: 300000 });
log("intake: " + intake.status + " — " + intake.summary);

function skippedStage(reason) {
  return { status: "skipped", summary: reason, changes: [], blockers: [], nodesAfter: null, edgesAfter: null };
}

let importStage, ontology, induction, categorizing, normalization, cleaning, extraction;
let summarize = skippedStage("Summarize runs only in dream jobs.");
let candidates = skippedStage("Candidate scan runs only in dream jobs.");
let queryStage = skippedStage("Query stage runs only in query jobs.");

if (category === "query") {
  extraction = skippedStage("Query jobs extract nothing.");
  importStage = skippedStage("Query jobs import nothing.");
  ontology = skippedStage("Query jobs run no ontology pass.");
  induction = skippedStage("Query jobs run no ontology induction.");
  categorizing = skippedStage("Query jobs do not categorize.");
  normalization = skippedStage("Query jobs never merge or normalize identities.");
  cleaning = skippedStage("Query jobs do not clean.");
  log("query mode: all write stages skipped by design — answering only.");

  phase("query");
  queryStage = await agent(stagePrompt("query",
    "CATEGORY 'query' — answer the job's question from THIS graph only, via the AGENTIC ANSWERING LOOP (skill §8), with READ-ONLY tools: ~/workspace/custom-connectors/custom.relate/bin/relate-search <graph> \"<question>\" (hybrid entry; add --rerank when the fused order looks breadth-heavy; add --triplets when the question asks how entities relate — the returned fact lines are the citable unit), ~/workspace/custom-connectors/custom.relate/bin/relate node <graph> <slug> (one node + its neighbors), ~/workspace/custom-connectors/custom.relate/bin/relate query <graph> '<static cypher>' for neighborhoods the search does not surface, and label/type census via relate labels/types <graph>. THE LOOP: (1) CLASSIFY — an entity/local question enters via relate-search; a corpus/global question enters via community summaries + the label census, then drills into the communities that matter. (2) ACT with the tool that fits the gap. (3) SELF-CHECK after every round: can every claim you would make be sourced to a retrieved node, edge, fact sentence, or document? What is still missing? (4) Run another round aimed at exactly that gap — max 4 rounds; stop when the check passes or a round adds nothing. (5) SYNTHESIZE only from retrieved material. GROUNDING RULE (absolute): every factual claim traces to this graph; name your sources in the summary (node names, document titles, fact sentences); if the graph does not contain the answer, put exactly \"that's not in this graph\" in the summary and stop — never fill gaps from general knowledge, memory, or outside sources, and label any inference as inference, kept separate. Put the grounded answer in `summary` (it becomes the request's result text) and one entry per retrieved source in `changes` (slug / type / fact). WRITE NOTHING to the graph in this stage. Status: 'done' when the loop produced a grounded answer or an honest not-in-graph; 'blocked' only when the job names no question or a tool failed — name it in blockers. A query job that closes 'done' without an answer in its summary is a false done — never do that.",
    { intake }), { key: "query", label: "Query — agentic GraphRAG answering loop", schema: stageSchema, timeoutMs: 900000 });
  log("query: " + queryStage.status + " — " + queryStage.summary);
} else if (category !== "dream") {
phase("ontology");
ontology = await agent(stagePrompt("ontology",
  "Applies when category is 'ontology' or 'full-pipeline', or the task asks for a schema/ontology pass. DETERMINISTIC FIRST: take the graph's census from the CLI — ~/workspace/custom-connectors/custom.relate/bin/relate labels <graph> and ~/workspace/custom-connectors/custom.relate/bin/relate types <graph> (slug = graphName) — never from improvised queries. The governing schema is the house ontology at ~/workspace/custom-connectors/custom.relate/ontologies/house-memory-graph.ttl (index: ~/workspace/custom-connectors/custom.relate/ONTOLOGIES.md): read it and compare the census against it; produce the canonical schema (labels, types, key properties per label) and report any drift from the house schema explicitly in your result. Standardization renames run through the typed tool: ~/workspace/custom-connectors/custom.relate/bin/relate rename <graph> <class|property> <old> <new> — never improvise rename Cypher. If the job's task text names an ontology preset (schema.org, FOAF, PROV-O, OWL-Time, SKOS, Dublin Core, W3C ORG, House), resolve the name to its pack file (schema-org.jsonld, foaf.rdf, prov-o.ttl, owl-time.ttl, skos.rdf, dcterms.rdf, org.ttl, house-memory-graph.ttl — all in ~/workspace/custom-connectors/custom.relate/ontologies/) and read that file as the source document for this pass, using the ONTOLOGIES.md mapping (FOAF/schema.org = people and organizations, PROV-O = provenance, OWL-Time = temporal patterns, SKOS = categories, Dublin Core = documents). Standards are never imported wholesale as graph DATA (their terms become ontology-stamp nodes, not content nodes). APPLYING = STAMPING INTO THE GRAPH (Johnny's rule: apply the OWL to the graph, not independently) — AND IT IS A TOOL CALL, NOT HAND-WRITTEN CYPHER: when the job APPLIES an ontology — a preset apply, or an ontology job whose task says to apply/adopt/stamp one, including the house ontology — run exactly: ~/workspace/custom-connectors/custom.relate/bin/relate stamp <graph> <preset> (preset = the one the task names; if none is named, 'house'), then ~/workspace/custom-connectors/custom.relate/bin/relate reconcile <graph>. The stamp tool materializes the FULL applied vocabulary into the graph from the pack file (one (:Ontology) node with name/sourceFile/version/appliedAt, its (:OntologyClass) and (:OntologyProperty) nodes carrying their standard-term mappings, DEFINES_CLASS/DEFINES_PROPERTY edges), keyed by NAME within the graph (one node per class/property name, definedBy accumulating across ontologies), so re-applying is a structural no-op; the reconcile tool then merges any pre-existing duplicate bookkeeping nodes (same name, several nodes — e.g. from earlier per-ontology stamps) into the keyed nodes, re-pointing DEFINES edges and deleting only the duplicate OntologyClass/OntologyProperty nodes, never content. Build your stage result from the two tools' JSON verbatim: stamp counts and the reconciliation report (names merged, nodes removed) go in changes/summary exactly as the tools report them. If a tool exits with an error, return status 'failed' with its error — never fall back to hand-written stamp Cypher. If a job only ASKS about an ontology without applying it, consult the file and run neither tool. After an apply, the stamped in-graph ontology GOVERNS the graph: import and categorizing conform new data to it, and the verifier checks the graph's data against it. On a blank or tiny graph with no apply requested, deliver the house canonical schema as your summary and mark status 'done' with no writes. BLANK-GRAPH RULE: if the graph carries NO stamped ontology yet (no (:Ontology) nodes in the census) and any stage of this job will write data, stamp 'house' first via the same stamp+reconcile tool calls even when the category is not ontology/full-pipeline — write-batch refuses every label on an unstamped graph, so an unstamped writing job can only fail or silently write nothing. If the category does not call for it, return 'skipped'.",
  { intake }), { key: "ontology", label: "Ontology — schema pass", schema: stageSchema, timeoutMs: 600000 });
log("ontology: " + ontology.status + " — " + ontology.summary);

phase("induction");
induction = await agent(stagePrompt("induction",
  "Applies ONLY when category is 'ontology' or 'full-pipeline' AND induction was requested: the job arg induce is set (see INDUCTION FLAG in the shared context) OR the task text asks for induction / a draft ontology / vocabulary discovery over the corpus. Otherwise return 'skipped' naming that induction was not requested. AUTO-ONTOLOGY INDUCTION (NVIDIA steal — deterministic profile first, ONE reasoning step under a restrictive contract, landing as a DRAFT that is never stamped): (A) DETERMINISTIC CORPUS PROFILE — tool output only, no reasoning. Run exactly: ~/workspace/custom-connectors/custom.relate/bin/relate counts <graph>, ~/workspace/custom-connectors/custom.relate/bin/relate labels <graph>, ~/workspace/custom-connectors/custom.relate/bin/relate types <graph>; then these READ-ONLY queries via ~/workspace/custom-connectors/custom.relate/bin/relate query <graph> '<statement>' (static statements exactly as written, no interpolated values): (1) pattern census: MATCH (a)-[r]->(b) RETURN labels(a)[0] AS fromLabel, type(r) AS type, labels(b)[0] AS toLabel, count(*) AS uses ORDER BY uses DESC (2) property census: MATCH (n) UNWIND keys(n) AS k RETURN k AS key, count(*) AS uses ORDER BY uses DESC (3) stamped terms: MATCH (oc:OntologyClass) RETURN oc.name AS name ORDER BY name — and the same statement with OntologyProperty in place of OntologyClass (4) corpus text: MATCH (n) WHERE n.name IS NOT NULL RETURN n.slug AS slug, labels(n)[0] AS label, n.name AS name, n.summary AS summary LIMIT 1000. From (4), compute term frequencies by this fixed procedure: lowercase the name+summary text, split on non-alphanumeric characters, drop tokens shorter than 3 chars and this stopword list (the, and, for, with, from, that, this, are, was, were, has, have, its, their, they, them, then, than, into, over, under, per, via), count the rest. This profile (census, pattern census, property census, stamped-term lists, top terms with counts) is the ONLY evidence base for step B — quote its numbers in your result. (B) ONE REASONING STEP — propose a draft ontology under this RESTRICTIVE CONTRACT (modeled on NVIDIA's term_extractor): (i) propose a class or property ONLY with corpus evidence — at least 2 supporting nodes OR at least 3 term mentions — and attach the evidence (counts plus up to 3 example slugs) to every proposed term; a term below the evidence floor is NOT proposed: it is recorded as an un-promoted discovery count instead (skill §2 vocabulary discovery — counted, visible, never silently absorbed, never silently dropped). (ii) ACCOUNTING: every content node in the corpus (exclude the Ontology/OntologyClass/OntologyProperty/Decision/ReviewItem/SpaceSignal bookkeeping labels) is accounted for EXACTLY ONCE — it fits a class already stamped in-graph (those classes are ALREADY DEFINED and are never re-proposed) or exactly one proposed class; a node fitting neither is named explicitly as unassignable residue. (iii) Prefer ONE class per coherent corpus family; a second class only for a true junction/mixed family, with the junction evidence stated. (iv) FORBIDDEN relationship classes: no IS_A, PART_OF, ROLE_OF, RELATED_TO or any generic/taxonomic link; a proposed object property must be a specific verb attested by actual edges in the pattern census or by repeated co-occurrence in the profile, with its attesting pattern (fromLabel, type, toLabel, uses) cited. (v) Synonyms/aliases only when explicitly written in corpus text ('also known as', a parenthetical) — never inferred. (vi) Dated or versioned copies of one family get a qualifying prefix on ONE class, not separate classes. (C) WRITE THE DRAFT — a Turtle file at ~/workspace/relate-space/ontology-drafts/<graphName>-draft-<today's date as YYYY-MM-DD>.ttl (create the folder first: mkdir -p ~/workspace/relate-space/ontology-drafts). Format follows the house pack: a header comment block (graph slug, date, the line 'DRAFT — uncertified induction output; NEVER stamped directly; stamping requires a separate approved ontology job', the profile headline numbers, the accounting result, the un-promoted discovery counts), then @prefix lines for owl/rdfs/xsd plus a draft prefix dr: <https://ontology.muse.local/draft/<graphName>#>, then one block per proposed class (dr:Name a owl:Class ; rdfs:label \"Name\" ; rdfs:comment \"<definition>. Evidence: <counts, example slugs>.\"), per proposed object property (a owl:ObjectProperty ; rdfs:domain ; rdfs:range naming proposed or already-defined classes), and per proposed datatype property (a owl:DatatypeProperty). Naming: labels PascalCase; object properties UPPER_SNAKE; datatype properties camelCase. (D) FILE THE REVIEW ITEM: run ~/workspace/custom-connectors/custom.relate/bin/relate review-add <graph> low-confidence '<subject-json>' '<choices-json>' with subject-json = {\"kind\":\"ontology-draft\",\"graph\":\"<graphName>\",\"draftPath\":\"<the draft path>\",\"proposedClasses\":<n>,\"proposedProperties\":<m>,\"summary\":\"<one line: what the draft proposes and its strongest evidence>\"} and choices-json = [\"approve-for-stamping-job\",\"revise-draft\",\"discard-draft\"]. HARD PROHIBITIONS: never run relate stamp in this stage (a draft is never stamped by the pipeline — stamping is a separate approved ontology job); never write the draft into the ontologies/ pack folder (drafts live only in ontology-drafts/); write no graph data other than the review item. Your result: summary carries the profile headline (content nodes by label, pattern count, top 5 terms with counts) and the proposal counts; changes lists the draft path and the review-add output verbatim; if any profile step fails, return status 'failed' with the tool's error in blockers — never propose from a partial profile.",
  { intake, ontology }), { key: "induction", label: "Induction — auto-ontology draft (never stamped)", schema: stageSchema, timeoutMs: 900000 });
log("induction: " + induction.status + " — " + induction.summary);

phase("extraction");
extraction = await agent(stagePrompt("extraction",
  "Applies when category is 'import', 'processing', or 'full-pipeline' AND the source named in the job is prose (a text/markdown file or pasted text). TRIPLET EXTRACTION (the Cognee contract — this stage is what makes imports produce FACT edges instead of only document attachments): (1) Run ~/workspace/custom-connectors/custom.relate/bin/relate chunks <source-file> — deterministic chunks plus the extraction contract (schema + rules) as JSON. (2) For EACH chunk, fill the contract: nodes (most complete name, elementary type stamped in this graph's ontology, description grounded in the chunk) and edges (snake_case relationship naming a stamped object property, plus the MANDATORY one-sentence fact using the endpoint names) — filling the contract is your reasoning step; obey its rules exactly (elementary types, most-complete-name coreference, no outside knowledge, numbers stay in facts/descriptions). Save each chunk's extraction as a JSON file {source: {slug: <the SourceDocument slug for this source>, path: <the source path>, name: <the document's name>}, nodes: [...], edges: [...]}. (3) Apply each chunk with ~/workspace/custom-connectors/custom.relate/bin/relate extract <graph> <file> — the tool validates the contract, computes identity slugs (the same entity merges at write time across chunks and documents), and writes through write-batch; a contract violation refuses that chunk whole — fix the extraction JSON and re-apply, never route around a refusal. (4) When every chunk is applied, run ~/workspace/custom-connectors/custom.relate/bin/relate embed-edges <graph> so the new fact sentences are embedded for triplet retrieval. Report per-chunk extracted/applied numbers and the run totals from the tools' JSON. If the named source is structured data (a table/JSON dataset) rather than prose, return 'skipped' naming that — the import stage handles structured sources. If the category does not call for importing, return 'skipped'.",
  { intake, ontology }), { key: "extraction", label: "Extraction — triplet extraction (Cognee contract)", schema: stageSchema, timeoutMs: 900000 });
log("extraction: " + extraction.status + " — " + extraction.summary);

phase("import");
importStage = await agent(stagePrompt("import",
  "Applies when category is 'import', 'processing', or 'full-pipeline', or the task explicitly asks to import/load/add data. Read the source named in the job (a file path, URL, or pasted dataset reference in the task text) and extract nodes and relationships from it (extraction is your reasoning step). Emit the extraction as a batch JSON file — every node/edge keyed by slug, every fact carrying its provenance (which source, which passage) — and apply it ONLY via ~/workspace/custom-connectors/custom.relate/bin/relate write-batch <graph> <batch.json>: write-batch is the only sanctioned write path (it validates each item against the in-graph ontology and the live graph, requires provenance, and MERGEs on slug so re-runs do not duplicate). Never write extracted data with your own Cypher or direct API calls. Facts write-batch rejects (ontology validation, missing provenance) come back in its JSON: report them as blockers with the tool's reasons, do not route around the rejection. If no usable source is named and the category requires one, return status 'blocked' naming the missing source. If the category does not call for importing, return 'skipped' after confirming counts are unchanged. ONTOLOGY CONFORMANCE: if the target graph carries a stamped in-graph ontology ((:Ontology) nodes linked by DEFINES_CLASS/DEFINES_PROPERTY), conform everything you write to it — node labels must be class names the stamp defines and edge types property names it defines; data that fits no defined class/property is reported as a blocker (ontology drift), never written under an invented label. CONTRADICTIONS (deterministic detection): BEFORE writing, run ~/workspace/custom-connectors/custom.relate/bin/relate scan-conflicts <graph> and record its JSON in your result; AFTER writing, run it again — conflicts the scan surfaces that involve facts you just wrote are handled now: for each, record both sides and their sources in your result, make the superseded-vs-undecidable call (that call is your reasoning), and if verifiably superseded execute it via the typed tool ~/workspace/custom-connectors/custom.relate/bin/relate supersede <graph> <fact-ref-json> <batch.json>; if undecidable, mark the pair contested (contested: true + contestedWith on both facts) and add a review item with the explicit choices (keep A / keep B / keep both as disputed) — write no resolution. Never overwrite or delete the old fact. EXTRACTION HANDOFF: for prose sources the extraction stage has already applied the fact edges via relate extract; your remaining work is the SourceDocument bookkeeping (the doc node exists — confirm its sourcePath and leave summary/category to their stages) and any STRUCTURED source (tables/JSON) the extraction stage skipped, via write-batch as above. If extraction covered the source completely, confirm the counts and finish — never duplicate its writes.",
  { intake, ontology }), { key: "import", label: "Import — load job source", schema: stageSchema, timeoutMs: 900000 });
log("import: " + importStage.status + " — " + importStage.summary);

phase("categorizing");
categorizing = await agent(stagePrompt("categorizing",
  "Applies when category is 'categorizing' or 'full-pipeline', or the task asks to categorize/classify/tag. DETERMINISTIC FIRST: run ~/workspace/custom-connectors/custom.relate/bin/relate categorize <graph> — it applies the ontology's category rules itself (the fixed house mapping: Person -> 'person', Group -> 'group', SourceDocument -> 'people-page' / 'groups-page' / 'index' / 'profile' / 'standing-file' by sourcePath, 'document' as the fallback for any other source) and writes those categories. Your reasoning is ONLY for the residue list the tool returns (nodes its rules could not determine): decide those from the node's label, properties, and content — never from a guess about a real-world identity — list every residue decision in changes, and apply residue decisions ONLY via ~/workspace/custom-connectors/custom.relate/bin/relate write-batch <graph> <batch.json>, never hand-written Cypher. Report how many nodes landed in each category and list any nodes you could not categorize as blockers with their keys. ONTOLOGY CONFORMANCE: if the target graph carries a stamped in-graph ontology, the classes and categories you assign must be the ones it defines (its OntologyClass nodes and the house category set) — a node that fits no defined class is reported as a blocker, never forced into an invented category. If the graph is empty or the category does not call for it, return 'skipped' with the reason.",
  { intake, importStage, ontology }), { key: "categorizing", label: "Categorizing — classify every node", schema: stageSchema, timeoutMs: 600000 });
log("categorizing: " + categorizing.status + " — " + categorizing.summary);

phase("normalization");
normalization = await agent(stagePrompt("normalization",
  "Applies when category is 'normalization' or 'full-pipeline', or the task asks to normalize. DETERMINISTIC CANDIDATES: run ~/workspace/custom-connectors/custom.relate/bin/relate normalize-scan <graph> and adjudicate ONLY the candidate pairs it returns (its fixed rules surface them: same normalized handle/name, shared identifiers, format drift) — do not go hunting for pairs the scan did not surface. Mechanical fixes (consistent name casing, handle formats — strip leading @, lowercase platform handles — date formats (ISO), stable key properties) are emitted as a batch JSON and applied ONLY via ~/workspace/custom-connectors/custom.relate/bin/relate write-batch <graph> <batch.json>. Merges: decide ONLY scan candidates, merge ONLY with evidence per the hard rules, list every merge with its evidence in changes, and execute merges ONLY via the typed tool ~/workspace/custom-connectors/custom.relate/bin/relate merge <graph> <winner-slug> <loser-slug> <basis-json> (basis = the scan rule that surfaced the pair + the evidence; the tool records the loser's full pre-merge state on a Decision node, so every merge is reversible with relate unmerge — write-batch CANNOT merge and must never be asked to). Report counts before/after. CONTRADICTIONS: normalization is where duplicates surface, and DETECTION IS THE TOOL'S, not yours: run ~/workspace/custom-connectors/custom.relate/bin/relate scan-conflicts <graph> before you start and again after any merge or write, and work from its JSON. When a merge-candidate pair carries incompatible facts (different live values for a single-valued property such as legalName or sourcePath, or conflicting edges between the same pair), that is a contradiction, not a merge: record both sides and their sources in your result, and resolve ONLY via the typed supersede tool (verifiably superseded: ~/workspace/custom-connectors/custom.relate/bin/relate supersede <graph> <fact-ref-json> <batch.json> — retire-and-link as one command; the old fact is never overwritten or deleted) or contested marking (contested: true plus a contestedWith note on both facts) plus a review item naming the explicit human choices (keep A / keep B / keep both as disputed). Never resolve a contradiction by silently picking a winner, and never merge two nodes whose facts contradict each other without recording the contradiction. RESOLUTION FUNNEL (Graphiti/Utopia steal — REPORT-ONLY machinery that runs BEFORE the adjudication above, whenever this stage runs): (1) BLOCKING — the candidate pairs are exactly the normalize-scan output; a pair the scan did not surface is not_compared, never a non-match, and is reported as such when the task asks about it. (2) PAIRWISE SCORING — run ~/workspace/custom-connectors/custom.relate/bin/relate similar-scan <graph> 0.50 and attach each blocked pair's raw cosine from its output, matched by the unordered slug pair; a blocked pair absent from the similar-scan output gets cosine null with the reason (a node unembedded, or the pair below the 0.50 floor) — never estimate or invent a cosine. Report every pair in changes in this exact shape: 'FUNNEL pair: <a> <-> <b> | rule <rule> | evidence <evidence> | cosine <value or null>'. (3) CLUSTER QA — group the scored pairs into clusters (connected components over the pair graph) and report each cluster in changes in this shape: 'FUNNEL cluster: members <comma-separated slugs> | pairs <p> of <possible> possible | density <p/possible rounded to 2dp>'; flag BRIDGE pairs — a pair whose removal splits its cluster into two groups, or a node whose pairs join two otherwise-dense sub-clusters — in this shape: 'FUNNEL bridge: <a> <-> <b> joins <side1 slugs> and <side2 slugs>'; flag any cluster with density under 0.5 as sparse in its cluster line (large + sparse is the false-merge shape, skill §5). The funnel itself merges NOTHING and writes NOTHING: it produces the scored, cluster-checked candidate set that the adjudication above — and only that adjudication, with evidence-ladder evidence — may act on through the typed merge tool. If the category does not call for it, return 'skipped'.",
  { intake, importStage, ontology, categorizing }), { key: "normalization", label: "Normalization — names, handles, dedupe", schema: stageSchema, timeoutMs: 600000 });
log("normalization: " + normalization.status + " — " + normalization.summary);

phase("cleaning");
cleaning = await agent(stagePrompt("cleaning",
  "Applies when category is 'cleaning' or 'full-pipeline', or the task asks to clean / run a data-quality check. DETERMINISTIC AUDIT BASELINE: first run ~/workspace/custom-connectors/custom.relate/bin/relate verify <graph> and take the audit numbers its gates report (isolated nodes, missing slugs, duplicate slugs, coverage) from its JSON — do not re-derive them with improvised queries. FINDINGS ARE THE TOOL'S: run ~/workspace/custom-connectors/custom.relate/bin/relate clean-scan <graph> (read-only findings: duplicates, self-references, isolated nodes, undeclared labels/types, missing key properties, empty-string properties) and act ONLY on its findings. Property-level fixes go out as a batch JSON via ~/workspace/custom-connectors/custom.relate/bin/relate write-batch <graph> <batch.json>; findings no tool can fix (structural orphans, anything needing a judgment call) are reported as blockers with exact counts and example keys — never improvise structural fixes. A pure check with no fixes needed is status 'done' with the audit numbers in the summary. If the category does not call for it, return 'skipped'.",
  { intake, importStage, ontology, categorizing, normalization }), { key: "cleaning", label: "Cleaning — data quality", schema: stageSchema, timeoutMs: 600000 });
log("cleaning: " + cleaning.status + " — " + cleaning.summary);
} else {
  extraction = skippedStage("Dream jobs never import or extract new sources.");
  importStage = skippedStage("Dream jobs never import new sources.");
  ontology = skippedStage("Dream jobs run no ontology pass; the house ontology pack still governs the verify stage's Part A gates.");
  induction = skippedStage("Dream jobs never induce ontologies; a draft is a schema artifact, not a consolidation.");
  categorizing = skippedStage("Dream jobs do not re-categorize.");
  normalization = skippedStage("Dream jobs never merge or normalize identities.");
  cleaning = skippedStage("Dream jobs never delete or clean; consolidation only.");
  log("dream mode: import/ontology/categorizing/normalization/cleaning skipped by design — consolidation only.");

  phase("summarize");
  summarize = await agent(stagePrompt("summarize",
    "DREAM STAGE — applies only when category is 'dream'. For EVERY SourceDocument node in the target graph that is missing a 'summary' property: read its source content from the file at its 'sourcePath' property, write a faithful summary of that content (2-4 sentences, grounded only in the file — never invent facts the file does not contain), and SET the 'summary' property on the node ONLY via ~/workspace/custom-connectors/custom.relate/bin/relate write-batch <graph> <batch.json> (one batch carrying every summary as a property update on its existing node — write-batch is the only sanctioned write path for reasoning-stage writes; never set properties through the raw Relate API or your own Cypher). Documents that already have a summary are left untouched. If a document has no sourcePath or its file cannot be read, leave it unsummarized and list it in blockers with the reason — never fabricate a summary. Write nothing else: no new nodes, no edges, no other properties. Report documents total, the missing-summary count before, how many you summarized, and the still-missing count after (re-query to confirm).",
    { intake }), { key: "summarize", label: "Summarize — fill SourceDocument summaries", schema: stageSchema, timeoutMs: 900000 });
  log("summarize: " + summarize.status + " — " + summarize.summary);
}

phase("embeddings");
const embeddings = await agent(stagePrompt("embeddings",
  "DETERMINISTIC STEP — a tool call, not hand work. Applies when category is 'embeddings', 'full-pipeline', or 'dream', or the task asks to embed / vectorize. Run exactly: ~/workspace/custom-connectors/custom.relate/bin/relate embed-missing <graph> (slug = graphName). The tool owns everything mechanical: which nodes lack an 'embedding', text composition per node, the local embeddinggemma runtime (Ollama, 768-dim), and storing embedding/embedding_dim/embedding_model exactly as previous passes did. Build your stage result from its JSON verbatim (how many embedded, how many already had vectors, model/dim as reported). Do NOT call Ollama yourself, do NOT compose texts, do NOT write vectors with your own Cypher; if the tool exits with an error, return status 'failed' with its error in blockers. DREAM MODE (category 'dream'): the same single tool call — the tool's contract governs node selection, and the run's verify stage gates the outcome (if control-plane nodes got embedded in a dream run, that surfaces as a verifier discrepancy, not something you fix by improvisation). SIMILAR_TO: this stage never creates SIMILAR_TO edges in a dream run (the candidate scan reports pairs as text only); in non-dream runs, a similarity pass happens only when the task explicitly asks for one — run the typed tool ~/workspace/custom-connectors/custom.relate/bin/relate similar <graph> <threshold> for it (lead-grade SIMILAR_TO edges), never an improvised one. EDGE FACTS (non-dream only): after embed-missing, also run ~/workspace/custom-connectors/custom.relate/bin/relate embed-edges <graph> — it embeds the fact sentences the extraction stage wrote onto fact edges (symmetric eg2-sym-v1 format) so triplet retrieval can rank them; build that part of your result from its JSON too. Dream runs skip embed-edges (dream writes node properties only). If the graph is empty or the category does not call for it, return 'skipped' with the reason.",
  { intake, importStage, ontology, categorizing, normalization, cleaning, summarize }), { key: "embeddings", label: "Embeddings — EmbeddingGemma pass", schema: stageSchema, timeoutMs: 900000 });
log("embeddings: " + embeddings.status + " — " + embeddings.summary);

phase("communities");
const communities = await agent(stagePrompt("communities",
  "Applies when category is 'communities', 'full-pipeline', or 'dream', or the task asks for community detection / clustering / communizing. DETERMINISTIC CORE: run ~/workspace/custom-connectors/custom.relate/bin/relate communities <graph> — deterministic label propagation over the real edges; it writes each node's 'community' property itself and returns the partition as JSON. Your reasoning is ONLY the per-community summary text (size, dominant labels/categories, hub nodes — read those from the tool's JSON and the labels/types census; do not recompute the partition): write a one-paragraph summary per community into your stage summary. If the ontology stage defined Community nodes, create them (with MEMBER_OF edges) via ~/workspace/custom-connectors/custom.relate/bin/relate write-batch <graph> <batch.json>, otherwise the property alone is enough. Communities are a structural fact about the graph, not an identity claim — never present two nodes as the same entity because they share a community. DREAM MODE (category 'dream'): the same tool run refreshes the assignments; then set a 'communitySummary' property on every content node holding the one-line summary of that node's community, applied via write-batch (properties only — in dream mode do not create Community nodes). If the graph is empty or the category does not call for it, return 'skipped' with the reason.",
  { intake, importStage, ontology, categorizing, normalization, cleaning, embeddings }), { key: "communities", label: "Communities — detection and summaries", schema: stageSchema, timeoutMs: 900000 });
log("communities: " + communities.status + " — " + communities.summary);

if (category === "dream") {
  phase("candidates");
  candidates = await agent(stagePrompt("candidates",
    "DREAM STAGE — applies only when category is 'dream'. CANDIDATE SCAN (report-only): run the deterministic tool ~/workspace/custom-connectors/custom.relate/bin/relate similar-scan <graph> 0.60 — it computes pairwise RAW cosine over content nodes (Person/Group/SourceDocument) carrying an 'embedding' property and returns the pairs; it writes nothing (never pull vectors into your own context to hand-compute cosines, and never use Relate's native vector.similarity.cosine, which returns (1+cos)/2, not raw cosine). Take the top pairs from its JSON (at most 10, only pairs scoring 0.60 or higher) and report each in changes as a LEAD-GRADE finding in this exact shape: 'LEAD pair: <slugA> <-> <slugB> cosine <score>'. These pairs are leads for a human or a later evidence-based job — never identity claims. HARD RULES for this stage: write NOTHING to the graph — no SIMILAR_TO edges, no merges, no property writes; node and edge counts after this stage must be identical to before it. If fewer than two content nodes carry embeddings, return status 'done' with zero candidates found and say why in the summary.",
    { intake, summarize, embeddings, communities }), { key: "candidates", label: "Candidates — lead-grade similarity scan (report only)", schema: stageSchema, timeoutMs: 900000 });
  log("candidates: " + candidates.status + " — " + candidates.summary);
}

const allStages = { intake, extraction, importStage, ontology, induction, categorizing, normalization, cleaning, summarize, embeddings, communities, candidates, queryStage };

phase("verify");
let verify = await agent(
  CTX + "\n\nYOU ARE THE INDEPENDENT VERIFIER for this relate-pipeline run (job category: " + category + "). DETERMINISTIC GATES FIRST: run exactly ~/workspace/custom-connectors/custom.relate/bin/relate verify <graph> (slug = graphName). Its JSON is the gate result — passed, the real node/edge counts, and per-gate evidence/discrepancies covering every gate enumerated below. Take nodes/edges/passed from the tool output; do NOT re-derive them with your own queries, and never override a tool failure with your own judgment. YOUR remaining job is the claim cross-check (a deterministic comparison — no new queries): compare the stage reports against the tool's numbers (totals, label/type census, category/community/embedding/summary coverage, and the concrete counts stages claimed — an import count, a merge count, an embedding count, a community size) and add a discrepancy for every claim the tool's numbers contradict, naming the stage and both numbers. If the tool itself exits with an error, return passed=false with the tool's error as the discrepancy. CANONICAL GATE LIST (D-04 — one list, owned by the CLI): the `gates` object in the verify tool's JSON is the COMPLETE enumeration — currently 20 gates: totals, label_census, type_census, missing_slugs, duplicate_slugs, missing_category, category_values, normalization_consistency, embedding_coverage, embedding_uniformity, bitemporal_sanity, provenance, isolated_nodes, summary_gap, community_coverage, bitemporal_coverage, duplicate_classes, duplicate_properties, conflicts, similar_to_lead_grade. Do not enumerate, re-derive, or invent gates beyond that object: a gate this prompt expects that the CLI does not emit, or a CLI gate you ignore, is itself a discrepancy (name it). JOB-AWARE COVERAGE: the coverage gates — missing_category, embedding_coverage, community_coverage, normalization_consistency — fail THIS RUN only when the corresponding stage actually ran in this job (categorizing / embeddings / communities / normalization with status 'done' in the stage reports below); when the job never included that stage, a failing coverage gate goes in evidence as informational, never as a discrepancy — an import-only job is not failed for coverage it never claimed. summary_gap and bitemporal_coverage are informational always (the CLI marks them non-blocking in its own detail). Every other gate fails unconditionally. passed = the CLI's passed, OR (the only failing gates are job-unaware coverage gates per the rule above AND the claim cross-check found nothing). DREAM JOBS, additionally: node and edge counts must be IDENTICAL to the intake counts (a dream run writes properties only — summary, embedding/embedding_dim/embedding_model, community, communitySummary; no new nodes, no new edges, no SIMILAR_TO), summary/embedding/community coverage must not have gone down versus intake, and the candidate scan must have written nothing. QUERY JOBS, additionally: no stage may have written anything — node and edge counts identical to intake, and the query stage's summary must contain the grounded answer or the exact not-in-graph sentence; a query job whose summary answers nothing fails here even when every gate passes. Stage reports (JSON): " + JSON.stringify(allStages) + "\n\nReturn: passed (true only if the API state matches the stage claims), the real node/edge counts you measured, evidence lines (the queries you ran and what they returned), and every discrepancy you found.",
  { key: "verify-1", label: "Verify — independent API check", schema: verifySchema, timeoutMs: 300000 });
log("verify: passed=" + verify.passed + " nodes=" + verify.nodes + " edges=" + verify.edges);

if (!verify.passed && verify.discrepancies.length > 0) {
  const repair = await agent(stagePrompt("repair",
    "The independent verifier found discrepancies in this run: " + JSON.stringify(verify.discrepancies) + ". DETERMINISTIC FIXERS ONLY — run the typed tools that address the failure and nothing else: ~/workspace/custom-connectors/custom.relate/bin/relate reconcile <graph> when the failure involves duplicate ontology bookkeeping or stamp drift; ~/workspace/custom-connectors/custom.relate/bin/relate embed-missing <graph> when it involves embedding coverage; ~/workspace/custom-connectors/custom.relate/bin/relate categorize <graph> when it involves missing categories. Build your stage result from the tools' JSON. Discrepancies no tool covers stay OPEN — name them in blockers; never improvise a fix, and never edit data just to match a wrong stage claim (where a claim was simply wrong, state the correction plainly in your summary).",
    allStages), { key: "repair-2", label: "Repair — fix verifier discrepancies", schema: stageSchema, timeoutMs: 600000 });
  log("repair: " + repair.status + " — " + repair.summary);
  allStages.repair = repair;
  verify = await agent(
    CTX + "\n\nYOU ARE THE INDEPENDENT VERIFIER, second pass after a repair. Run ~/workspace/custom-connectors/custom.relate/bin/relate verify <graph> (slug = graphName) again and take passed, the real counts, and the gate results from its JSON exactly as in the first pass — no improvised queries. Cross-check the previously discrepant claims (" + JSON.stringify(verify.discrepancies) + ") against the new tool output and return passed, the real counts, evidence, and any remaining discrepancies. Stage reports including repair (JSON): " + JSON.stringify(allStages),
    { key: "verify-2", label: "Verify — second pass", schema: verifySchema, timeoutMs: 300000 });
  log("verify-2: passed=" + verify.passed + " nodes=" + verify.nodes + " edges=" + verify.edges);
}

phase("writeback");
let writeback = { status: "skipped", summary: "No requestId — nothing to write back to.", changes: [], blockers: [] };
if (requestId) {
  const finalStatus = verify.passed ? "done" : "failed";
  const stageList = category === "dream"
    ? [intake, summarize, embeddings, communities, candidates]
    : category === "query"
      ? [intake, queryStage]
      : [intake, ontology, induction, extraction, importStage, categorizing, normalization, cleaning, embeddings, communities];
  let resultText = "relate-pipeline (" + category + "): " + stageList.map(function (s) { return s.status; }).join(" / ") + ". Graph now: " + verify.nodes + " nodes, " + verify.edges + " edges. Verified: " + verify.passed + ". " + (verify.discrepancies.length ? ("Open discrepancies: " + verify.discrepancies.join("; ")) : "No open discrepancies.");
  if (category === "query") {
    resultText += " ANSWER — " + queryStage.summary + (queryStage.changes.length ? " Sources: " + queryStage.changes.join("; ") : "");
  }
  if (category === "dream") {
    resultText += " DREAM REPORT — summarized: " + summarize.summary + " Embedded: " + embeddings.summary + " Communities: " + communities.summary + " Candidates (lead-grade, report-only; nothing merged, no SIMILAR_TO written): " + candidates.summary + (candidates.changes.length ? " Pairs: " + candidates.changes.join("; ") : "");
  }
  writeback = await agent(
    CTX + "\n\nYOU ARE THE WRITEBACK STAGE. Use the artifact tools: call artifact.invoke_action with slug '" + spaceSlug + "', action_name 'updateAgentRequest', args {id: '" + requestId + "', status: '" + finalStatus + "', result: '" + resultText + "'}. Then call listAgentRequests and confirm the request now shows status '" + finalStatus + "'. Return the stage result with the confirmed status in your summary.",
    { key: "writeback", label: "Writeback — update Space request", schema: stageSchema, timeoutMs: 300000 });
  log("writeback: " + writeback.status + " — " + writeback.summary);
}

return {
  message: "relate-pipeline run complete for category '" + category + "'" + (task ? " — task: " + task : "") + ". Graph: " + verify.nodes + " nodes / " + verify.edges + " edges (independently verified, passed=" + verify.passed + ").",
  category: category,
  task: task,
  graph: graphName,
  apiBase: apiBase,
  requestId: requestId || null,
  stages: {
    intake: intake.status,
    extraction: extraction.status,
    query: queryStage.status,
    import: importStage.status,
    ontology: ontology.status,
    induction: induction.status,
    categorizing: categorizing.status,
    normalization: normalization.status,
    cleaning: cleaning.status,
    embeddings: embeddings.status,
    communities: communities.status,
    summarize: summarize.status,
    candidates: candidates.status,
    writeback: writeback.status
  },
  verification: { passed: verify.passed, nodes: verify.nodes, edges: verify.edges, evidence: verify.evidence, discrepancies: verify.discrepancies }
};